public struct LocalizationManager: Sendable {
    public static func tr(_ key: String, lang: UILanguage) -> String {
        if let langDict = strings[lang], let val = langDict[key] {
            return val
        }
        if let enDict = strings[.english], let val = enDict[key] {
            return val
        }
        return key
    }

